mapper.select:
SELECT DATE(call_time) AS date, COUNT(*) AS count
FROM algo_call_log
WHERE call_time >= #{startDate} AND call_time <= #{endDate}

    AND algorithm_type = #{algorithmType}

GROUP BY DATE(call_time)
ORDER BY date ASC

SELECT COUNT(*) FROM algo_call_log
WHERE call_time >= #{startDate} AND call_time <= #{endDate}

    AND algorithm_type = #{algorithmType}

SELECT COUNT(DISTINCT user_id) FROM algo_call_log
WHERE call_time >= #{startDate} AND call_time <= #{endDate}

    AND algorithm_type = #{algorithmType}
